// Offline support: precache the whole app, serve from cache, update in the background.
// The FILES list and VERSION are generated by scripts/build-sw.mjs.
const VERSION = '18fba8d21a';
const FILES = [
  "./",
  "./css/app.css",
  "./fonts/barlow-condensed-latin-500-normal.woff2",
  "./fonts/barlow-condensed-latin-600-normal.woff2",
  "./fonts/barlow-condensed-latin-700-normal.woff2",
  "./fonts/barlow-latin-400-italic.woff2",
  "./fonts/barlow-latin-400-normal.woff2",
  "./fonts/barlow-latin-500-normal.woff2",
  "./fonts/barlow-latin-600-normal.woff2",
  "./fonts/jetbrains-mono-latin-400-normal.woff2",
  "./icons/apple-touch-icon.png",
  "./icons/favicon.svg",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/maskable-512.png",
  "./index.html",
  "./js/app.js",
  "./js/data/common.js",
  "./js/data/index.js",
  "./js/data/ops/contour.js",
  "./js/data/ops/dynamic.js",
  "./js/data/ops/facing-slot.js",
  "./js/data/ops/holes.js",
  "./js/data/ops/pocket.js",
  "./js/data/reference.js",
  "./js/i18n.js",
  "./js/icons.js",
  "./js/search.js",
  "./js/util.js",
  "./js/views/fix.js",
  "./js/views/home.js",
  "./js/views/misc.js",
  "./js/views/op.js",
  "./js/views/palette.js",
  "./js/views/tools.js",
  "./js/viz/param-viz.js",
  "./js/viz/preview3d.js",
  "./manifest.webmanifest",
  "./vendor/three/addons/OrbitControls.js",
  "./vendor/three/three.module.min.js"
];
const CACHE = 'cadteach-' + VERSION;

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('cadteach-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  e.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(req, { ignoreSearch: true });
      const net = fetch(req).then((res) => { if (res.ok) cache.put(req, res.clone()); return res; }).catch(() => hit);
      return hit || net;
    }),
  );
});
